public class CategoryPlot_removeRangeMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private fields of CategoryPlot using reflection
     * since the provided API doesn't show a public way to add markers.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Map<Integer, ArrayList<Marker>> map, int index, Marker marker) throws Exception {
        Field field = CategoryPlot.class.getDeclaredField(map == null ? "foregroundRangeMarkers" : "backgroundRangeMarkers");
        // Actually we need to know which field to target. Let's detect based on the map passed.
        // But for simplicity in this test, we will target the specific field name.
    }

    private void setInternalMarkers(String fieldName, int index, ArrayList<Marker> markers) throws Exception {
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        if (map == null) {
            map = new HashMap<>();
            field.set(plot, map);
        }
        map.put(index, markers);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_MarkersNull_ReturnsTrue() throws Exception {
        // If the map entry for the index is null, it returns true.
        // We need to ensure the map exists but the key is absent or returns null.
        setInternalMarkers("foregroundRangeMarkers", 0, null);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertTrue(result);
    }

    @Test
    public void testRemoveRangeMarker_Background_MarkersNull_ReturnsTrue() throws Exception {
        setInternalMarkers("backgroundRangeMarkers", 0, null);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.BACKGROUND, true);
        assertTrue(result);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_RemoveSuccessful_NotifyTrue() throws Exception {
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setInternalMarkers("foregroundRangeMarkers", 0, markers);

        // Since fireChangeEvent is likely a protected method, we can't easily verify it 
        // without a spy, but we can verify the return value.
        CategoryPlot spyPlot = Mockito.spy(plot);
        // Note: Testing private/protected side effects like fireChangeEvent via Spy 
        // requires the method to be at least protected or package-private.

        boolean result = spyPlot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertTrue(result);
        assertFalse(markers.contains(mockMarker));
    }

    @Test
    public void testRemoveRangeMarker_Foreground_RemoveSuccessful_NotifyFalse() throws Exception {
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setInternalMarkers("foregroundRangeMarkers", 0, markers);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, false);

        assertTrue(result);
        assertFalse(markers.contains(mockMarker));
    }

    @Test
    public void testRemoveRangeMarker_Foreground_RemoveFailed_ReturnsFalse() throws Exception {
        ArrayList<Marker> markers = new ArrayList<>();
        Marker otherMarker = mock(Marker.class);
        markers.add(otherMarker);
        setInternalMarkers("foregroundRangeMarkers", 0, markers);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertFalse(result);
        assertTrue(markers.contains(otherMarker));
    }

    @Test
    public void testRemoveRangeMarker_Background_RemoveSuccessful() throws Exception {
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setInternalMarkers("backgroundRangeMarkers", 0, markers);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.BACKGROUND, true);

        assertTrue(result);
        assertFalse(markers.contains(mockMarker));
    }

    @Test
    public void testRemoveRangeMarker_Background_RemoveFailed() throws Exception {
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mock(Marker.class));
        setInternalMarkers("backgroundRangeMarkers", 0, markers);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.BACKGROUND, true);

        assertFalse(result);
    }
}
